/* One report model shared by the on-screen agreement and downloadable PDF. */
const Agreement=(()=>{
 function create(s,meta){
  if(!s.report||!s.guarantee||s.alloc.reduce((a,b)=>a+b,0)!==100)throw Error('Agreement is incomplete.');
  return {id:meta.id,date:meta.date,mode:meta.mode,roster:meta.roster||'Student 1: Kitala',rows:['Kitala','Nordland','Meridia','Pelagia'].map((name,i)=>({name,share:s.alloc[i],courses:s.supply*s.alloc[i]/100})),sections:[
   {title:'1. Decision and participating delegations',text:'The four fictional delegations - Kitala, Nordland, Meridia and Pelagia - adopt the revised equitable-access package by consensus. No objection remains under the written mandates used in this simulation. This records a simulated outcome, not real government consent.'},
   {title:'2. Allocation of the shared pool',text:`The available pool is ${s.supply} million vaccine courses, reduced from 100 million following a manufacturing disruption. The allocation below forms part of the adopted agreement.`},
   {title:'3. Financing and delivery support',text:`Nordland provides ${s.fund} million fictional credits of donor financing. Of this total, ${s.delivery} million credits are earmarked for delivery support in Pelagia; this is included in, not additional to, the donor commitment.`},
   {title:'4. Accountability and production',text:'Quarterly public reporting is included as a condition of donor support. The package includes a production purchase guarantee addressing Meridia\'s requirement. The exercise does not specify guarantee pricing, contracting terms or liability.'},
   {title:'5. Implementation follow-up',text:'The agreement commits resources and policy terms; it does not demonstrate completed delivery. Delegations must translate commitments into financing, procurement, distribution and reporting arrangements. Detailed owners, dates and delivery plans remain to be negotiated; they were not adopted in this exercise.'},
   {title:'6. Negotiation record',text:`Kitala opening approach: ${meta.opening==='national'?'Kitala requested 50% without additional conditions.':'Kitala proposed an equitable package and invited discussion of reporting and production commitments.'} Initial response to reporting: ${meta.initialReporting?'accepted':'rejected'}. ${meta.attempts} consensus check(s) took place; ${meta.failures} did not reach agreement. The final package includes reporting and a production guarantee.`},
   {title:'7. Learning and scope',text:'Kitala receives 28 million allocated courses against a scenario priority need of 40 million. Its 35% share would have yielded 35 million before the supply shock. Adoption therefore leaves a 12-million-course allocation gap even before delivery losses. Countries, resources and mandates are fictional. This independent WHO-inspired exercise is not an official WHO agreement or a validated digital twin.'}
  ]};
 }
 const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function html(r){return `<div class="report-meta">${escape(r.id)} · ${escape(r.date)}<br>${r.mode==='solo'?'Solo practice':'Shared-screen classroom'} · Adopted by simulated consensus<br>${escape(r.roster)}</div>`+r.sections.map((s,i)=>`<section class="agreement-section"><h3>${escape(s.title)}</h3><p>${escape(s.text)}</p>${i===1?`<table class="agreement-table"><thead><tr><th>Delegation</th><th>Share</th><th>Courses</th></tr></thead><tbody>${r.rows.map(x=>`<tr><th scope="row">${x.name}</th><td>${x.share}%</td><td>${x.courses} million</td></tr>`).join('')}<tr><th scope="row">Total</th><td>100%</td><td>80 million</td></tr></tbody></table>`:''}</section>`).join('')}
 // Minimal vector PDF: standard embedded PDF font references, ASCII content,
 // fixed two-page layout, byte-correct cross-reference table; no server needed.
 function pdf(r){
  const safe=s=>String(s).replace(/[^\x20-\x7e]/g,' ').replace(/([\\()])/g,'\\$1');
  function text(s,x,y,size=10,font='F1',color='0.16 0.23 0.24'){return `${color} rg BT /${font} ${size} Tf 1 0 0 1 ${x} ${y} Tm (${safe(s)}) Tj ET\n`}
  function wrap(s,max=87){const a=[];let line='';for(const word of s.split(/\s+/)){if((line+' '+word).trim().length>max){a.push(line);line=word}else line+=(line?' ':'')+word}if(line)a.push(line);return a}
  function base(n){let out='0.08 0.19 0.22 rg 0 725 595 117 re f\n';out+=text('ASSEMBLY / POLICY AGREEMENT',44,797,11,'F2','0.87 0.8 0.61');out+=text(n===1?'Equitable access to vaccines':'Agreement record & follow-up',44,762,23,'F2','1 1 1');out+=text(r.id+'  |  '+r.date,44,703,9);out+=text((r.mode==='solo'?'Solo practice':'Shared-screen classroom')+'  |  ADOPTED BY SIMULATED CONSENSUS',44,685,9,'F2');out+='0.75 0.8 0.77 RG 44 60 m 551 60 l S\n';out+=text('Independent educational simulation - not an official WHO document',44,43,8);out+=text(`${n} / 2`,524,43,8);return out}
  function section(s,y){let out=text(s.title,44,y,12,'F2');y-=22;for(const line of wrap(s.text)){out+=text(line,44,y);y-=15}return {out,y:y-20}}
  let p1=base(1),y=650;for(let i=0;i<4;i++){const s=section(r.sections[i],y);p1+=s.out;y=s.y;if(i===1){p1+='0.92 0.94 0.9 rg 44 '+(y-15)+' 507 24 re f\n';p1+=text('DELEGATION',54,y-7,9,'F2')+text('SHARE',300,y-7,9,'F2')+text('VACCINE COURSES',393,y-7,9,'F2');y-=34;for(const row of [...r.rows,{name:'Total',share:100,courses:80}]){p1+=text(row.name,54,y,10,row.name==='Total'?'F2':'F1')+text(row.share+'%',300,y)+text(row.courses+' million',393,y);y-=22}y-=10}}
  let p2=base(2);y=650;p2+=text('Student role allocation',44,y,12,'F2');y-=22;for(const line of wrap(r.roster)){p2+=text(line,44,y);y-=15}y-=20;for(let i=4;i<r.sections.length;i++){const s=section(r.sections[i],y);p2+=s.out;y=s.y}p2+=text('Reflection prompts',44,y,12,'F2');y-=25;for(const s of ['Which concession made agreement possible?','Whose priorities remained unmet after adoption?','What must happen next for these commitments to become delivery?']){p2+=text(s,44,y,10);y-=25}
  const streams=[p1,p2],objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [5 0 R 7 0 R] /Count 2 >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>'];streams.forEach((s,i)=>{objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents ${6+i*2} 0 R >>`);objects.push(`<< /Length ${s.length} >>\nstream\n${s}endstream`)});
  let out='%PDF-1.4\n',offsets=[0];objects.forEach((s,i)=>{offsets.push(out.length);out+=`${i+1} 0 obj\n${s}\nendobj\n`});const xref=out.length;out+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n`;for(const n of offsets.slice(1))out+=`${String(n).padStart(10,'0')} 00000 n \n`;out+=`trailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;return new TextEncoder().encode(out);
 }
 return {create,html,pdf};
})();
if(typeof module!=='undefined')module.exports=Agreement;
